code='def add_item(self,item):\n    if self.used == len(self.items):\n        print("Full")\n        return\n    for i in range(self.used):\n        if self.items[i] is item:\n            print("Already present")\n            return\n    self.items[self.used]=item\n    self.used+=1'
e(15,'d',22,5,'Construct','Construct addMonster(MonsterM).',C+'Ifnotfullandnotalreadyexisting,addatcount,increment;otherwisecorrectmessage.',['B2.2.2','B2.3.2'],'B',28,'Capacitycheck,identitycheck,insert/count,errorbranches.','Shop uses a fixed-capacity Python list self.items,with self.used occupied entries at thefront andNone afterwards. Construct add_item(self,item). Add the same object only if absent andcapacity remains;otherwise print Full orAlready present. Use object identity,not equal names.',pts((1,'Checks self.used against listcapacity beforeinserting.'),(1,'Searches occupiedentries using is forobjectidentity.'),(1,'Reports duplicate anddoesnotalterstorage/count.'),(1,'Stores newitem at self.items[self.used] andincrementsused.'),(1,'Reports fullcapacity without overwriting anitem.')),solution=code,code=code,tests='from types import SimpleNamespace\nimport contextlib,io\na=object();b=object();shop=SimpleNamespace(items=[None,None],used=0)\nwith contextlib.redirect_stdout(io.StringIO()):\n add_item(shop,a);add_item(shop,a);add_item(shop,b);add_item(shop,object())\nassert shop.used==2 and shop.items==[a,b]',reason='Retains fixedcapacity/membershipbranching;identityrule prevents sourceMSname-equality shortcut incorrectlymergingdistinctobjects.')
