code='def recommend(items,target,score):\n    best=items[0]\n    best_score=score(best,target)\n    for item in items[1:]:\n        current=score(item,target)\n        if current>best_score or(current==best_score and item.stock>best.stock):\n            best=item\n            best_score=current\n    return best'
